from AlgorithmImports import *
import math


class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.closes = {ticker: [] for ticker in self.tickers}
        self.opens = {ticker: [] for ticker in self.tickers}
        self.red_streak = {ticker: 0 for ticker in self.tickers}

        self.rsi_avg_gain = None
        self.rsi_avg_loss = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if bar is not None:
                    bars[ticker] = bar

        # Update market-state data for every ticker that has a bar.
        for ticker, bar in bars.items():
            prior_close = self.closes[ticker][-1] if self.closes[ticker] else None

            if prior_close is not None:
                if bar.Close < prior_close:
                    self.red_streak[ticker] += 1
                else:
                    self.red_streak[ticker] = 0

            self.opens[ticker].append(float(bar.Open))
            self.closes[ticker].append(float(bar.Close))

            if ticker == "AAPL" and prior_close is not None:
                change = float(bar.Close) - prior_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.rsi_avg_gain is None:
                    self.rsi_seed_gains.append(gain)
                    self.rsi_seed_losses.append(loss)

                    if len(self.rsi_seed_gains) == 14:
                        self.rsi_avg_gain = sum(self.rsi_seed_gains) / 14.0
                        self.rsi_avg_loss = sum(self.rsi_seed_losses) / 14.0
                        self.aapl_rsi = self.CalculateRsi(
                            self.rsi_avg_gain, self.rsi_avg_loss
                        )
                else:
                    self.rsi_avg_gain = (
                        self.rsi_avg_gain * 13.0 + gain
                    ) / 14.0
                    self.rsi_avg_loss = (
                        self.rsi_avg_loss * 13.0 + loss
                    ) / 14.0
                    self.aapl_rsi = self.CalculateRsi(
                        self.rsi_avg_gain, self.rsi_avg_loss
                    )

        # Do not evaluate any rules unless every subscribed ticker has today's bar.
        if len(bars) != len(self.tickers):
            return

        spy_close_history = self.closes["SPY"]
        aapl_close_history = self.closes["AAPL"]

        # Strategy A needs today's and yesterday's fully formed 100-day SMAs.
        strategy_a_ready = len(spy_close_history) >= 101

        # Strategy B needs a fully formed 14-day RSI.
        strategy_b_ready = (
            len(aapl_close_history) >= 15 and self.aapl_rsi is not None
        )

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and strategy_a_ready:
            yesterday_sma = sum(spy_close_history[-101:-1]) / 100.0
            today_sma = sum(spy_close_history[-100:]) / 100.0
            yesterday_close = spy_close_history[-2]
            today_close = spy_close_history[-1]

            if yesterday_close >= yesterday_sma and today_close < today_sma:
                self.MarketOrder(
                    self.symbols["SPY"], -self.strategy_a_shares
                )
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and strategy_b_ready:
            if self.aapl_rsi > 60.0:
                self.MarketOrder(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and strategy_a_ready:
            yesterday_sma = sum(spy_close_history[-101:-1]) / 100.0
            today_sma = sum(spy_close_history[-100:]) / 100.0
            yesterday_close = spy_close_history[-2]
            today_close = spy_close_history[-1]

            if yesterday_close <= yesterday_sma and today_close > today_sma:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = int(math.floor(target_value / today_close))

                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and strategy_b_ready:
            if self.red_streak["AAPL"] >= 3:
                aapl_close = aapl_close_history[-1]
                if self.Portfolio.Cash >= 20000.0:
                    quantity = int(math.floor(20000.0 / aapl_close))

                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

    def CalculateRsi(self, average_gain, average_loss):
        if average_loss == 0.0:
            return 100.0
        if average_gain == 0.0:
            return 0.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
